calc.mjs.text:
/**
 * The `calculateTrueUp` inputs, in the form's own ids. Single-sourced here so
 * a field added to the form is shareable the day it ships rather than
 * silently dropped by an encoder that never learned about it. Also the exact
 * set `usage.mjs`'s `SCENARIO_FIELDS` persists locally.
 *
 * `renewalDate` and `noticeDays` are deliberately NOT in this list -- they
 * are session-only for the *saved* scenario (a renewal date from last quarter
 * would be actively wrong reappearing on a later, unrelated visit) -- but as
 * of 2026-09-06 `share.mjs` carries both anyway, on its own field lists
 * alongside this one. A share link describes the *same* renewal the sender is
 * looking at right now, not a future one, so the staleness argument above
 * does not apply to it, and the recipient needs `renewalDate`/`noticeDays` to
 * see the same notice-deadline verdict the sender saw.
 */
export const INPUT_FIELDS = Object.freeze(['purchased', 'used', 'price', 'months', 'overageRate', 'seatMinimum']);

export function calculateTrueUp({ seatsPurchased, seatsUsed, monthlyPrice, monthsRemaining = 12, overageRatePct = 0, seatMinimum = 0 }) {
  const purchased = Number(seatsPurchased);
  const used = Number(seatsUsed);
  const price = Number(monthlyPrice);
  const months = Number(monthsRemaining);
  const overageRate = Number(overageRatePct);
  const minimum = Number(seatMinimum);
  if (![purchased, used, price, months, overageRate, minimum].every(Number.isFinite) || purchased < 0 || used < 0 || price < 0 || months < 0 || overageRate < 0 || minimum < 0) {
    throw new Error('Values must be non-negative numbers');
  }
  const unused = Math.max(0, purchased - used);
  const extra = Math.max(0, used - purchased);
  // A contracted seat minimum means unused seats below that floor cannot
  // actually be dropped at renewal -- the vendor bills for them either way.
  // droppableSeats is what a true-up can realistically remove; lockedByMinimum
  // is the unused seats the minimum still forces you to keep paying for.
  const droppableSeats = Math.max(0, purchased - Math.max(used, minimum));
  const lockedByMinimum = unused - droppableSeats;
  const monthlyAvoidable = droppableSeats * price;
  // Vendor overage is often list price plus a contracted premium. 0% keeps
  // the same-price default so existing worksheets stay comparable.
  const monthlyOverage = extra * price * (1 + overageRate / 100);
  return {
    purchased,
    used,
    unused,
    extra,
    overageRatePct: overageRate,
    seatMinimum: minimum,
    droppableSeats,
    lockedByMinimum,
    utilizationPercent: purchased === 0 ? (used === 0 ? 0 : Infinity) : (used / purchased) * 100,
    monthlyAvoidable,
    remainingAvoidable: monthlyAvoidable * months,
    annualAvoidable: monthlyAvoidable * 12,
    monthlyOverage,
    remainingOverage: monthlyOverage * months,
    annualOverage: monthlyOverage * 12,
  };
}

export function formatMoney(value, currency = '$') {
  return `${currency}${value.toFixed(2)}`;
}

const MS_PER_DAY = 24 * 60 * 60 * 1000;

function parseDateInput(value) {
  if (value === undefined || value === null || value === '') return null;
  const date = value instanceof Date ? value : new Date(`${value}T00:00:00`);
  return Number.isNaN(date.getTime()) ? null : date;
}

// Most seat contracts do not let you reduce at will -- reductions land at
// renewal, and renewal itself is often gated behind a written-notice window
// (e.g. "must notify 60 days before the term ends or it auto-renews at the
// full count"). A true-up that only compares purchased vs. used ignores
// whether there is still time to act on that comparison. If the notice
// deadline has already passed, the "avoidable" spend calculateTrueUp reports
// is not avoidable this cycle at all -- it renews regardless of usage, and
// the number that matters is how much of that is now locked in and when the
// *next* window opens.
export function evaluateNoticeDeadline({ renewalDate, noticeDays = 0, today } = {}) {
  const renewal = parseDateInput(renewalDate);
  if (!renewal) return null;
  const days = Number(noticeDays);
  if (!Number.isFinite(days) || days < 0) {
    throw new Error('Notice period must be a non-negative number of days');
  }
  const now = parseDateInput(today) || (today instanceof Date ? today : new Date());
  const deadline = new Date(renewal.getTime() - days * MS_PER_DAY);
  const daysUntilDeadline = Math.round((deadline.getTime() - now.getTime()) / MS_PER_DAY);
  const daysUntilRenewal = Math.round((renewal.getTime() - now.getTime()) / MS_PER_DAY);
  return {
    renewalDate: renewal,
    noticeDays: days,
    deadline,
    daysUntilDeadline,
    daysUntilRenewal,
    deadlinePassed: daysUntilDeadline < 0,
    deadlineSoon: daysUntilDeadline >= 0 && daysUntilDeadline <= 14,
  };
}

function formatDate(date) {
  return date.toLocaleDateString('en-CA'); // YYYY-MM-DD, unambiguous regardless of locale
}

export function noticeMessage(result, notice) {
  if (!notice) return null;
  if (result.droppableSeats <= 0) return null; // nothing this window's deadline could have saved
  if (notice.deadlinePassed) {
    const nextDeadline = new Date(notice.deadline.getTime() + 365 * MS_PER_DAY);
    return `The notice deadline (${formatDate(notice.deadline)}) passed ${Math.abs(notice.daysUntilDeadline)} day${Math.abs(notice.daysUntilDeadline) === 1 ? '' : 's'} ago. This renewal auto-renews at the full ${result.purchased} seats regardless of usage -- the ${result.droppableSeats}-seat saving above is not avoidable this cycle. Assuming an annual term, the next window to act closes around ${formatDate(nextDeadline)}; confirm the real date on your agreement.`;
  }
  if (notice.deadlineSoon) {
    return `Notice deadline in ${notice.daysUntilDeadline} day${notice.daysUntilDeadline === 1 ? '' : 's'} (${formatDate(notice.deadline)}). Submit the ${result.droppableSeats}-seat reduction before then or this renewal auto-renews at the full count and the saving above is lost for the term.`;
  }
  return `Notice deadline: ${formatDate(notice.deadline)} (${notice.daysUntilDeadline} days away). The ${result.droppableSeats}-seat saving above is only real if the reduction is submitted by then.`;
}

export function reviewMessage(result) {
  if (result.extra > 0) {
    const premium = result.overageRatePct > 0
      ? ` at the entered ${result.overageRatePct}% overage premium`
      : '';
    return `This review is over the purchased count by ${result.extra} seat${result.extra === 1 ? '' : 's'}${premium}. That is ${formatMoney(result.annualOverage)} of extra annual spend if the overage continues, or ${formatMoney(result.remainingOverage)} through the remaining term.`;
  }
  if (result.lockedByMinimum > 0) {
    return `${result.unused} seat${result.unused === 1 ? ' is' : 's are'} unused, but the contracted ${result.seatMinimum}-seat minimum locks in ${result.lockedByMinimum} of them regardless. Only ${result.droppableSeats} seat${result.droppableSeats === 1 ? '' : 's'} can actually be dropped: ${formatMoney(result.annualAvoidable)} over a full year if those go.`;
  }
  return `A seat review could release ${formatMoney(result.annualAvoidable)} over a full year if the unused seats are not renewed.`;
}

share.mjs.text:
// Puts a scenario's numbers in the URL itself, so a seat review can be sent to
// a manager or finance partner without uploading anything -- seat counts and
// per-seat price are commercially sensitive, which is the same reason
// usage.mjs never sends them anywhere either. Single-sourced from calc.mjs's
// INPUT_FIELDS so a field added to the form is shareable the day it ships.
import { INPUT_FIELDS as FIELDS } from './calc.mjs';

// `noticeDays` is not one of calculateTrueUp's own INPUT_FIELDS -- it only
// feeds evaluateNoticeDeadline -- but it has to ride in the same link. Found
// 2026-09-06 by `platform/pages/roundtrip.mjs`, the only failure across 720
// pages: a reviewer who typed a 60-day notice period, copied the link, and
// sent it to a manager watched that manager's copy of the page silently show
// 0 instead.
const EXTRA_NUMBER_FIELD_IDS = Object.freeze(['noticeDays']);

// The one date field on the form. It is deliberately excluded from the saved
// scenario in usage.mjs -- a renewal date from last quarter is stale next
// quarter, and reappearing on a later, unrelated visit would be actively
// wrong -- but that reasoning does not apply to a share link at all: the
// recipient is reviewing the *same* renewal the sender just looked at, not a
// future one. Leaving it out of the link, as it was until 2026-09-06,
// silently hid the entire notice-deadline verdict on the recipient's page --
// evaluateNoticeDeadline() returns null with no renewalDate, so a warning
// like "this auto-renews at the full seat count unless you act by <date>"
// that the sender saw simply never rendered for the person the review was
// sent to. `roundtrip.mjs` cannot catch this half on its own: it only reads
// `input[type="number"]`, and this is `type="date"`.
const DATE_FIELD_IDS = Object.freeze(['renewalDate']);

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

// Shape-checked rather than calendar-checked: a link carrying "2026-13-40" is
// passed through to calc.mjs's evaluateNoticeDeadline, which already treats
// an unparseable date as "no deadline" the same way an empty field does. This
// only guards against a fragment that is not a date-shaped string at all.
function usableDate(value) {
  return typeof value === 'string' && ISO_DATE_RE.test(value) ? value : null;
}

export function encodeInputs(input) {
  const params = new URLSearchParams();
  for (const field of [...FIELDS, ...EXTRA_NUMBER_FIELD_IDS]) {
    const value = Number(input?.[field]);
    if (Number.isFinite(value) && value >= 0) params.set(field, String(value));
  }
  for (const field of DATE_FIELD_IDS) {
    const value = usableDate(input?.[field]);
    if (value !== null) params.set(field, value);
  }
  return params.toString();
}

export function decodeInputs(value) {
  const params = new URLSearchParams(String(value || '').replace(/^[?#]/, ''));
  const result = {};
  for (const field of [...FIELDS, ...EXTRA_NUMBER_FIELD_IDS]) {
    if (!params.has(field)) continue;
    const number = Number(params.get(field));
    if (Number.isFinite(number) && number >= 0) result[field] = number;
  }
  for (const field of DATE_FIELD_IDS) {
    if (!params.has(field)) continue;
    const value = usableDate(params.get(field));
    if (value !== null) result[field] = value;
  }
  return result;
}

usage.mjs.text:
const KEY = 'saas-seat-true-up:usage';
const OPT_OUT = 'saas-seat-true-up:opt-out';
const SCENARIO_KEY = 'saas-seat-true-up:scenario';
const SCENARIO_FIELDS = ['purchased', 'used', 'price', 'months', 'overageRate', 'seatMinimum'];

function storage() {
  try {
    return typeof localStorage !== 'undefined' ? localStorage : null;
  } catch {
    return null;
  }
}

export function usageAllowed() {
  if (typeof navigator !== 'undefined' && (navigator.doNotTrack === '1' || navigator.globalPrivacyControl)) {
    return false;
  }
  const ls = storage();
  if (!ls) return false;
  // recordEvent() (and the #disable click handler) call this with no
  // try/catch of their own -- a blocked getItem must not throw out of here.
  try {
    return ls.getItem(OPT_OUT) !== 'true';
  } catch {
    return false;
  }
}

export function recordEvent(eventName) {
  if (!usageAllowed()) return;
  try {
    const ls = storage();
    if (!ls) return;
    const current = JSON.parse(ls.getItem(KEY) || '{}');
    current[eventName] = (current[eventName] || 0) + 1;
    ls.setItem(KEY, JSON.stringify(current));
  } catch { /* Private browsing must not break the calculator. */ }
}

export function disableUsage() {
  try {
    const ls = storage();
    if (!ls) return;
    ls.setItem(OPT_OUT, 'true');
    ls.removeItem(KEY);
  } catch { /* optional measurement */ }
}

export function saveScenario(store, scenario) {
  const ls = store || storage();
  if (!ls) return false;
  try {
    const value = {};
    for (const field of SCENARIO_FIELDS) {
      const number = Number(scenario?.[field]);
      if (!Number.isFinite(number) || number < 0) return false;
      value[field] = number;
    }
    ls.setItem(SCENARIO_KEY, JSON.stringify(value));
    return true;
  } catch {
    return false;
  }
}

export function loadScenario(store) {
  const ls = store || storage();
  if (!ls) return null;
  try {
    const value = JSON.parse(ls.getItem(SCENARIO_KEY) || 'null');
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
    if (['purchased', 'used', 'price', 'months'].some((field) => typeof value[field] !== 'number' || !Number.isFinite(value[field]) || value[field] < 0)) {
      return null;
    }
    if (value.overageRate == null) value.overageRate = 0;
    if (typeof value.overageRate !== 'number' || !Number.isFinite(value.overageRate) || value.overageRate < 0) {
      return null;
    }
    if (value.seatMinimum == null) value.seatMinimum = 0;
    if (typeof value.seatMinimum !== 'number' || !Number.isFinite(value.seatMinimum) || value.seatMinimum < 0) {
      return null;
    }
    return value;
  } catch {
    return null;
  }
}

export function clearScenario(store) {
  const ls = store || storage();
  if (!ls) return;
  try {
    ls.removeItem(SCENARIO_KEY);
  } catch { /* optional persistence */ }
}
